def transform(g):
    h=len(g); w=len(g[0])
    rows=[r for r in range(h) if 5 in g[r]]
    cols=[c for c in range(w) if any(g[r][c]==5 for r in rows)]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    s=r1-r0+1
    out=[[0]*w for _ in range(h)]
    def ring(r,c,sz,col):
        for i in range(c,c+sz): out[r][i]=col; out[r+sz-1][i]=col
        for i in range(r,r+sz): out[i][c]=col; out[i][c+sz-1]=col
    k=0
    while True:
        sz=s-8*k
        if sz<1: break
        if k>0 and not (sz>=4 or sz==1): break
        r,c=r0+4*k,c0+4*k
        ring(r,c,sz,5)
        if sz>=4: ring(r+1,c+1,sz-2,2)
        if sz>=6: ring(r+2,c+2,sz-4,5)
        if sz==4: pass
        k+=1
    return out

